import runpy,json
from pathlib import Path
S=Path(__file__).resolve().parents[1];e=runpy.run_path(str(S/'work/write_superetf_basic.py'));add=e['add'];out=e['out'];cost=e['cost']
dd='每日模式對仍持倉日close插同價type=x平開，免額外成本與交易次數、內部position不變；交易時不插。這不是實際市場日平。'
add('SOX','持續固定方向持有或每日當沖，依可選參考價設日內百分比停損停利，退出後可尾盤或次日回補。','日內風控與反覆持有',['空手每天open按固定方向建立，數量按當日open換名目。一般留倉沿原數量，不每日等額調整。','停損／停利後若非當沖且部位回補選當日收盤，當日close再進；其他情況等下個資料日open。尾盤量仍用當天open換的數量。'],['多側先open<=損線，以open再扣停損滑價%；否則low<=線，以線扣滑價；再high>=停利線按線退。空側方向對稱且停損成交加滑價。','沒觸價時若當沖、已達正留倉天數上限或整份最後筆，收盤平；否則保存昨收並持有。沒有價格訊號決定是否下單。'],[cost,'損線初始參考一律由「留倉開高停損基準」決定取進場或當日open；有昨收時，開高且其基準選平盤、或開低且低側基準選平盤，才改昨收。','留倉停利可選進場、當日open或昨收；缺昨收時平盤先退回open。OHLC無先後路徑，程式固定損優先於利。'],['開低停損基準的進場價選項沒有獨立實作；它只有選平盤時改昨收，其他仍沿開高欄決定的初始參考。','尾盤再進只更新共用entryprice，未更新核心私有進場價變數；若下日保護選進場價，可能仍用上一筆已退出的進場。','最後一筆若先觸價退出再尾盤補回，走的是空手分支，會繞過另一分支的最後筆強平，留下新倉。','停利跳空仍用停利線價而非更有利open；成本另按成交價百分比扣，不能把停損滑價當作已包含所有成本。'],{'停利比':'基準×(1±此百分比)，多high／空low到線退，直接按線不給有利跳空open。','停損比':'損基準×(1∓此百分比)，開盤跳損先open、否則盤中high/low按線退，再套停損滑價。','停損滑價':'僅停損成交再往不利方向乘此百分比：多賣減、空補加；交易成本仍另扣。','當沖':'真則未停損停利時每日close平，退出後不尾盤補；假可留倉或按部位回補選項。','留倉最多天數':'正值時計數>=上限的未觸價日close平，初次開盤進設0，尾盤補設1；0不依天數退。','留倉停利基準':'進場價取核心保存入場、開盤價取本日open、平盤價有昨收才用昨收；尾盤補未同步核心入場。','留倉開高停損基準':'先決定所有情況的損基準取核心進場或open；開高且選平盤時改昨收。','留倉開低停損基準':'僅開低且選平盤時改昨收；選進場沒有另外切換，仍沿開高欄初始參考。','部位回補':'非當沖且觸價退出，當日收盤可立即同方向補；次日開盤則留空到次資料日。一般天數平倉不走同日補回。','計算DD方式':dd})
add('SOX2','固定方向持續持有，從昨收日損線與入場總損線取較緊一條；固定資料週期收盤全平、次日重建調量。','雙基準停損與週期調量',['空手每日open按固定方向建倉，數量按該日open換固定名目；此時把日損參考重設open、總損參考重設此次進場。','持有時不每天調量，停損後下一資料日open自動再建；沒有等待價格訊號。'],['多取max(昨收×(1−日損%),入場×(1−總損%))為較緊線，空取min相應上方線；先open跳損按open退，否則盤中low/high到線按線退。','資料索引i+1加組合偏移後，恰整除正留倉天數的日close全平；週期不因中途停損歸零，次日open重新換量。','沒有資料末筆必平分支，最後仍有倉可只作每日DD虛擬估值，並非實際已平。'],[cost,'組合分散僅把週期計數加int(參考進場比例×留倉天數)，不延後第一次open進場；每個商品仍可第一筆就進。','每筆風控先日損與入場損取緊，不含停利、追蹤停損或額外停損滑價參數；交易成本仍逐邊百分比。'],['留倉天數<=0停用週期全平，並非禁止交易；若無觸損可一路持有至資料尾且仍未真平。','分散只是平倉／重調週期錯開，Description所述各商品不同日期初進並未由此核心實作。','沒有session改變的獨立換約處理，風控參考與逐筆收益依載入日資料價格，需和資料調整方式一起判讀。'],{'日停損比':'正常留倉按昨收換百分比日線；新進當天參考改本日open，和進場損取較緊線。','進場停損比':'此次入場價換總損百分比，只有重新建倉才重設，和每日損取緊。','留倉天數':'正N用(i+1+偏移)%N==0日close平，不受中間停損重開影響；<=0不依週期退出。','組合回測進場':'分散加int(組合參考進場×留倉天數)到週期索引，不分散不加；並未延後首次開倉。','計算DD方式':dd})
(S/'analysis/SuperETF.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print('Wrote ETF SOX pair')
